-- seed_cathy_story.sql  (Job 4: Cathy, her whole story)
-- Cathy M. registers for labour migration to Dubai. She has no agent yet, her first payment fails.
-- Rows owned by this file: Cathy's user and client profile, her application,
-- 1 stage_history row, 1 failed payment (5 rows).
-- Safe to run on its own, and safe to run twice. Ids are generated by the server;
-- other rows are found by natural keys (phone, stage_order, role_name).
-- Source: PDF p.5 (users), p.6 (client_profiles), p.7 (applications), p.9 (payments), p.10 (stage_history)

BEGIN;

-- 0. SCHEMA FIX (PDF p.10: from_stage_id must allow empty values, empty only for the first entry)
--    Safe to repeat: it does nothing if the column already allows empty values.
--    Remove this line once the stage_history table itself has been corrected.
ALTER TABLE stage_history ALTER COLUMN from_stage_id DROP NOT NULL;

-- 1. BASE BLOCK (identical in every seed file: roles, stages, staff)
INSERT INTO roles (role_name) VALUES ('Client'), ('Field Agent'), ('Data Entry Staff'), ('Secretary'), ('Director')
ON CONFLICT DO NOTHING;

INSERT INTO pipeline_stages (stage_name, stage_order) VALUES
    ('Registered', 1), ('Docs Pending', 2), ('Verification', 3), ('Payment', 4),
    ('Processing', 5), ('Ready', 6), ('Departed', 7)
ON CONFLICT DO NOTHING;

INSERT INTO users (full_name, email, phone, password_hash, role_id) VALUES
    ('Brian K.',  'brian.k@alsj.example',  '0700000001', '$2a$10$fMn/Zfqq88Ai2E1hJLfhe.rV8Dp4AA0H8xvx5r8NdSs4GhKZpzUEO', (SELECT role_id FROM roles WHERE role_name = 'Field Agent')),
    ('Diana S.',  'diana.s@alsj.example',  '0700000002', '$2a$10$fMn/Zfqq88Ai2E1hJLfhe.rV8Dp4AA0H8xvx5r8NdSs4GhKZpzUEO', (SELECT role_id FROM roles WHERE role_name = 'Data Entry Staff')),
    ('Grace T.',  'grace.t@alsj.example',  '0700000003', '$2a$10$fMn/Zfqq88Ai2E1hJLfhe.rV8Dp4AA0H8xvx5r8NdSs4GhKZpzUEO', (SELECT role_id FROM roles WHERE role_name = 'Secretary')),
    ('Moses L.',  'moses.l@alsj.example',  '0700000004', '$2a$10$fMn/Zfqq88Ai2E1hJLfhe.rV8Dp4AA0H8xvx5r8NdSs4GhKZpzUEO', (SELECT role_id FROM roles WHERE role_name = 'Director'))
ON CONFLICT DO NOTHING;

INSERT INTO staff_profiles (user_id, employee_no, date_hired)
SELECT user_id, v.employee_no, v.date_hired::date
FROM users u
JOIN (VALUES ('0700000001', 'ALSJ-001', '2024-03-01'), ('0700000002', 'ALSJ-002', '2024-06-15'),
             ('0700000003', 'ALSJ-003', '2025-01-10'), ('0700000004', 'ALSJ-004', '2023-09-01'))
     AS v(phone, employee_no, date_hired) ON v.phone = u.phone
ON CONFLICT DO NOTHING;

-- 2. PARENT ROWS (Cathy's own, so inserted here)
-- Cathy M.: user, client profile, application (parent rows, safe to repeat)
INSERT INTO users (full_name, email, phone, password_hash, role_id)
VALUES ('Cathy M.', NULL, '0700000012', '$2a$10$fMn/Zfqq88Ai2E1hJLfhe.rV8Dp4AA0H8xvx5r8NdSs4GhKZpzUEO', (SELECT role_id FROM roles WHERE role_name = 'Client'))
ON CONFLICT DO NOTHING;

INSERT INTO client_profiles (user_id, national_id, date_of_birth, address, preferred_language)
SELECT user_id, 'CF90112233', '1996-08-03', 'Entebbe', 'EN' FROM users WHERE phone = '0700000012'
ON CONFLICT DO NOTHING;

INSERT INTO applications (client_id, assigned_agent_id, current_stage_id, service_type, destination, travel_purpose, preferred_travel_date, status)
SELECT u.user_id, NULL, (SELECT stage_id FROM pipeline_stages WHERE stage_order = 1), 'LABOUR_MIGRATION', 'Dubai', 'Hospitality work', '2027-01-20', 'ACTIVE'
FROM users u
WHERE u.phone = '0700000012'
  AND NOT EXISTS (SELECT 1 FROM applications a WHERE a.client_id = u.user_id);

-- 3. STAGE HISTORY (the first row: no previous stage, no actor = the system)
INSERT INTO stage_history (application_id, from_stage_id, to_stage_id, changed_by, changed_at)
SELECT (SELECT application_id FROM applications WHERE client_id = (SELECT user_id FROM users WHERE phone = '0700000012')), NULL, (SELECT stage_id FROM pipeline_stages WHERE stage_order = 1), NULL, '2026-10-10 14:00+03'
WHERE NOT EXISTS (SELECT 1 FROM stage_history WHERE application_id = (SELECT application_id FROM applications WHERE client_id = (SELECT user_id FROM users WHERE phone = '0700000012')) AND from_stage_id IS NULL);

-- 4. THE FAILED PAYMENT (no reference and no completion time, as the PDF requires for FAILED)
INSERT INTO payments (application_id, amount, currency, payment_method, payer_phone, transaction_reference, status, initiated_at, completed_at)
SELECT (SELECT application_id FROM applications WHERE client_id = (SELECT user_id FROM users WHERE phone = '0700000012')), 30000, 'UGX', 'AIRTEL_MONEY', '0700000012', NULL, 'FAILED', '2026-10-11 09:00+03', NULL
WHERE NOT EXISTS (SELECT 1 FROM payments WHERE application_id = (SELECT application_id FROM applications WHERE client_id = (SELECT user_id FROM users WHERE phone = '0700000012')) AND amount = 30000);

COMMIT;
